#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for optional OpenMP parallelization */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "bicg.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)(i % m) / m;
  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)(i % n) / n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % n)/n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local aliases to enable better vectorization
     and avoid pessimistic alias analysis.
   - Parallelize over the outer i-loop with OpenMP while using an
     OpenMP array reduction for s[], so that each element of A[i][j]
     is still used once to update both s[j] and q[i] (good cache use).
   - Hoist invariant loads (r[i], A[i]) out of the inner loop.
   - Accumulate q[i] in a register (q_i) and write back once per row.
   - Keep the original loop structure in the sequential (no-OpenMP)
     case; when compiled without -fopenmp, all #pragma omp directives
     are ignored and the code reduces to a straightforward, optimized
     sequential implementation with identical structure to the original.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Create restrict-qualified aliases to help the compiler optimize.
     Types:
       A_ : pointer to rows of length m (row-major matrix)
       s_, q_, p_, r_ : 1D vectors
  */
  DATA_TYPE (* restrict A_)[m]   = A;
  DATA_TYPE * restrict s_        = s;
  DATA_TYPE * restrict q_        = q;
  const DATA_TYPE * restrict p_  = p;
  const DATA_TYPE * restrict r_  = r;

#pragma scop
  /* Parallel region used so that threads are created only once
     for both loops. When compiled without OpenMP support, all
     #pragma omp directives are ignored and the code executes
     sequentially but still benefits from the aliasing hints. */
#pragma omp parallel private(i, j)
  {
    /* First, initialize s to zero. This loop has no dependencies. */
#pragma omp for schedule(static)
    for (i = 0; i < _PB_M; i++)
      s_[i] = SCALAR_VAL(0.0);

    /* Main BiCG computation.
       We parallelize across rows (index i). Each thread works on a
       subset of rows of A and q. The vector s is updated via an
       OpenMP array reduction so that each thread maintains a private
       partial sum of s and the runtime combines them afterwards.

       Memory access pattern:
       - A_[i][j] is accessed with j as the innermost index, which is
         contiguous and cache-friendly (row-major).
       - p_ and s_ are accessed linearly in j, also cache-friendly.
    */
#pragma omp for schedule(static) reduction(+:s_[:_PB_M])
    for (i = 0; i < _PB_N; i++)
      {
        const DATA_TYPE r_i = r_[i];          /* hoist r[i] */
        const DATA_TYPE * restrict Ai = A_[i];/* pointer to row i of A */
        DATA_TYPE q_i = SCALAR_VAL(0.0);      /* accumulate q[i] in a register */

        for (j = 0; j < _PB_M; j++)
          {
            const DATA_TYPE A_ij = Ai[j];
            s_[j] += r_i * A_ij;
            q_i   += A_ij * p_[j];
          }

        q_[i] = q_i;
      }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
