/* Array initialization.
 *
 * Optimizations:
 *  - Precompute 1/m and 1/n to avoid repeated divisions.
 *  - Exploit that i < m and i < n to remove redundant modulo
 *    operations in the p and r initializations.
 *  - Keep A's initialization formula mathematically identical,
 *    but also reuse 1/n.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m))
{
