  const DATA_TYPE inv_n = SCALAR_VAL(1.0) / (DATA_TYPE)n;

  /* For these loops, i ranges in [0, m) and [0, n),
   * so i % m == i and i % n == i. */
  for (i = 0; i < m; i++)
    p[i] = (DATA_TYPE)i * inv_m;

  for (i = 0; i < n; i++) {
    r[i] = (DATA_TYPE)i * inv_n;
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE)((i * (j + 1)) % n) * inv_n;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("s");
  for (i = 0; i < m; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, s[i]);
  }
  POLYBENCH_DUMP_END("s");
  POLYBENCH_DUMP_BEGIN("q");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, q[i]);
  }
  POLYBENCH_DUMP_END("q");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce restrict-qualified local aliases for all arrays to
 *    improve the compiler's alias analysis and enable more
 *    aggressive vectorization.
 *  - Hoist invariant loads (r[i]) and accumulate q[i] in a
 *    scalar register (q_i) to reduce memory traffic.
 *  - Iterate over A by rows (i outer, j inner) as in the original
 *    code, which matches the row-major layout and preserves good
 *    cache behavior.
 *  - Use an OpenMP parallel for with an array-section reduction
 *    on s to exploit thread-level parallelism. When compiled
 *    without OpenMP support, the pragma is ignored and the code
 *    runs sequentially with the same semantics as the original.
 */
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Create restrict-qualified aliases to help the compiler
   * assume that these arrays do not overlap in memory.  We only
   * use the restrict-qualified aliases below, not the original
   * parameter names, so the restrict contract is respected. */
  DATA_TYPE (*restrict A_restrict)[m] = A;
  DATA_TYPE *restrict s_restrict       = s;
  DATA_TYPE *restrict q_restrict       = q;
  DATA_TYPE *restrict p_restrict       = p;
  DATA_TYPE *restrict r_restrict       = r;

#pragma scop
  /* Initialize s to zero.  This is separated from the main
   * parallel loop so that the reduction on s starts from a
   * known zero base value. */
  for (i = 0; i < _PB_M; i++)
    s_restrict[i] = SCALAR_VAL(0.0);

  /* Main BiCG kernel:
   *
   *   q[i] = sum_j A[i][j] * p[j]
   *   s[j] = sum_i r[i]    * A[i][j]
   *
   * The outer loop over rows (i) is parallelized. Each iteration:
   *  - Reads a single r[i] and row A[i][*].
   *  - Produces q[i] (no write-sharing between threads).
   *  - Contributes to the global reduction on s[j].
   *
   * The OpenMP array-section reduction
   *     reduction(+: s_restrict[:_PB_M])
   * gives each thread a private copy of s[0.._PB_M-1], accumulates
   * into that copy, and combines them at the end.  This preserves
   * the original mathematical result while enabling safe parallel
   * updates to s.
   *
   * If compiled without -fopenmp, this pragma is ignored and the
   * loop executes sequentially, exactly matching the original
   * computation.
   */
#pragma omp parallel for private(j) schedule(static) \
    reduction(+:s_restrict[:_PB_M])
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE r_i = r_restrict[i];
      DATA_TYPE q_i = SCALAR_VAL(0.0);
      DATA_TYPE *restrict A_row = A_restrict[i];

      /* Inner loop is over contiguous elements of A_row and p,
       * which maximizes spatial locality and enables efficient
       * vectorization. */
      for (j = 0; j < _PB_M; j++)
	{
	  DATA_TYPE A_ij = A_row[j];

	  /* Update s and q with the same A[i][j] load, preserving
	   * the fused-use pattern of the original kernel. */
	  s_restrict[j] += r_i * A_ij;
	  q_i           += A_ij * p_restrict[j];
	}

      /* Store the accumulated value of q[i] once, outside the
       * inner loop, to reduce memory traffic. */
      q_restrict[i] = q_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
