}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local aliases for all arrays to enable
     more aggressive vectorization and avoid unnecessary alias checks.
   - Parallelize the main loop over rows (i) with OpenMP when available.
   - Use an OpenMP array reduction on s[] so that each thread accumulates
     its own private copy and they are combined at the end. This preserves
     the mathematical result of:
         s[j] = sum_i r[i] * A[i][j]
     while exploiting parallelism.
   - Keep the loop nest structure friendly for the cache: we iterate over
     A by contiguous rows (j is the innermost loop), and access p[j] and
     s[j] with unit stride.
   - Provide a sequential fallback path when OpenMP is not enabled,
     preserving the exact original execution order.
*/
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases (arrays are disjoint in main). */
  DATA_TYPE (*restrict A_restrict)[m] = A;
  DATA_TYPE *restrict s_restrict = s;
  DATA_TYPE *restrict q_restrict = q;
  DATA_TYPE *restrict p_restrict = p;
  DATA_TYPE *restrict r_restrict = r;

#pragma scop

#ifdef _OPENMP

  /* Parallel region: zero s[] in parallel, then compute BiCG kernel.
     The reduction over s_restrict[0.._PB_M-1] lets OpenMP manage
     thread-local partial sums and combine them at the end. */
  #pragma omp parallel
  {
    /* Initialize s to zero in parallel. */
    #pragma omp for schedule(static)
    for (i = 0; i < _PB_M; i++)
      s_restrict[i] = SCALAR_VAL(0.0);

    /* BiCG kernel:
         q[i] = sum_j A[i][j] * p[j]
         s[j] = sum_i r[i] * A[i][j]
       Parallelized over i (rows). Each thread works on a subset of rows.
       The reduction clause creates per-thread copies of s[] that are
       combined at the end of the loop. */
    #pragma omp for schedule(static) reduction(+:s_restrict[:_PB_M])
    for (i = 0; i < _PB_N; i++)
      {
        DATA_TYPE qi = SCALAR_VAL(0.0);
        const DATA_TYPE ri = r_restrict[i];
        DATA_TYPE *restrict Ai = A_restrict[i];

        for (j = 0; j < _PB_M; j++)
          {
            const DATA_TYPE Aij = Ai[j];
            qi += Aij * p_restrict[j];
            s_restrict[j] += ri * Aij;
          }

        q_restrict[i] = qi;
      }
  }

#else  /* !_OPENMP: strictly sequential version matching the original code */

  /* Initialize s to zero (original behavior). */
  for (i = 0; i < _PB_M; i++)
    s_restrict[i] = SCALAR_VAL(0.0);

  /* Original BiCG kernel, but written with local aliases to
     improve vectorization and cache usage. */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE qi = SCALAR_VAL(0.0);
      const DATA_TYPE ri = r_restrict[i];
      DATA_TYPE *restrict Ai = A_restrict[i];

      for (j = 0; j < _PB_M; j++)
        {
          const DATA_TYPE Aij = Ai[j];
          qi += Aij * p_restrict[j];
          s_restrict[j] += ri * Aij;
        }

      q_restrict[i] = qi;
    }

#endif /* _OPENMP */

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, M, n, m);
  POLYBENCH_1D_ARRAY_DECL(s, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(q, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(p, DATA_TYPE, M, m);
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (m, n,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(r),
	      POLYBENCH_ARRAY(p));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_bicg (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(s),
	       POLYBENCH_ARRAY(q),
	       POLYBENCH_ARRAY(p),
	       POLYBENCH_ARRAY(r));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(s), POLYBENCH_ARRAY(q)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(s);
  POLYBENCH_FREE_ARRAY(q);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(r);

  return 0;
}
