#endif


/* Array initialization. */
static
void init_array (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m))
{
  int i, j;

  /* Precompute reciprocals to avoid a division in every iteration. */
  const DATA_TYPE inv_m = SCALAR_VAL(1.0) / (DATA_TYPE)m;
  const DATA_TYPE inv_n = SCALAR_VAL(1.0) / (DATA_TYPE)n;

  /* For 0 <= i < m, (i % m) == i, so we can drop the modulo. */
  for (i = 0; i < m; i++)
    p[i] = inv_m * (DATA_TYPE)i;

  for (i = 0; i < n; i++) {
    /* For 0 <= i < n, (i % n) == i, so we can drop the modulo. */
    r[i] = inv_n * (DATA_TYPE)i;

    /* A[i][j] = (i*(j+1) % n) / n
     * Hoist 1/n and perform the integer modulo before the final cast. */
    for (j = 0; j < m; j++) {
      int t = (i * (j + 1)) % n;
      A[i][j] = inv_n * (DATA_TYPE)t;
    }
  }
}


