/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Original computation:
     s[j] = sum_i r[i] * A[i][j]    (s = A^T * r)
     q[i] = sum_j A[i][j] * p[j]    (q = A * p)

   Optimizations applied:
   - Use restrict-qualified local pointers to help the compiler vectorize.
   - Initialize s in a separate loop (as before).
   - Parallelize over i (rows of A) using OpenMP.
   - Use an OpenMP array reduction on s to obtain the same result as the
     sequential accumulation while avoiding data races.
   - Keep the fused use of A for both q and s to preserve good cache locality.
   - Optionally block the j-loop (columns of A) with a tunable block size
     (BICG_J_BLOCK_SIZE) to improve cache reuse of A's rows, p, and s.
   - Use #pragma omp simd on the innermost loop to encourage SIMD vectorization.
*/
static
void kernel_bicg[[gnu::flatten, gnu::noinline]](int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
                 DATA_TYPE POLYBENCH_1D(s,M,m),
                 DATA_TYPE POLYBENCH_1D(q,N,n),
                 DATA_TYPE POLYBENCH_1D(p,M,m),
                 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i;

  /* Polybench loop bounds (may differ from raw m,n depending on configuration). */
  const int M_dim = _PB_M;
  const int N_dim = _PB_N;

  /* Local restrict-qualified aliases to help the compiler with alias analysis. */
  DATA_TYPE (*restrict A_)[M_dim] = A;
  DATA_TYPE *restrict s_ = s;
  DATA_TYPE *restrict q_ = q;
  DATA_TYPE *restrict p_ = p;
  const DATA_TYPE *restrict r_ = r;

#pragma scop
  /* Initialize s to zero as in the original code. */
  for (i = 0; i < M_dim; i++)
    s_[i] = SCALAR_VAL(0.0);

  /* Parallel region:
   * - We parallelize over the outer loop index i (rows of A).
   * - q_[i] is private to each iteration (each i written exactly once).
   * - s_ is shared and updated via an OpenMP array reduction, which
   *   guarantees that, element-wise, the final s_ is the sum over all
   *   iterations i, identical to the sequential program.
   *
   * When compiled without -fopenmp, this pragma is ignored and the
   * code executes sequentially, preserving the original behavior.
   */
#pragma omp parallel for schedule(static) reduction(+:s_[:M_dim])
  for (i = 0; i < N_dim; i++)
  {
    const DATA_TYPE r_i = r_[i];
    DATA_TYPE q_i = SCALAR_VAL(0.0);
    DATA_TYPE *restrict Ai = A_[i];

#if BICG_J_BLOCK_SIZE > 0
    /* Block the j-loop to improve locality of Ai, p_, and s_.
     * The remainder (when M_dim is not divisible by the block size)
     * is handled by the min() logic on j_end. */
    for (int jb = 0; jb < M_dim; jb += BICG_J_BLOCK_SIZE)
    {
      const int j_end = (jb + BICG_J_BLOCK_SIZE < M_dim)
                        ? jb + BICG_J_BLOCK_SIZE
                        : M_dim;

#     pragma omp simd reduction(+:q_i)
      for (int j = jb; j < j_end; j++)
      {
        const DATA_TYPE A_ij = Ai[j];

        /* q[i] accumulation: q_i += A[i][j] * p[j]; */
        q_i += A_ij * p_[j];

        /* s[j] accumulation: s[j] += r[i] * A[i][j]; */
        s_[j] += r_i * A_ij;
      }
    }
#else
    /* Simple unblocked version of the inner loop. */
#   pragma omp simd reduction(+:q_i)
    for (int j = 0; j < M_dim; j++)
    {
      const DATA_TYPE A_ij = Ai[j];

      q_i += A_ij * p_[j];
      s_[j] += r_i * A_ij;
    }
#endif

    /* Store q[i] once per row, as in the original code. */
    q_[i] = q_i;
  }
#pragma endscop

